def visible_rows(actions):
    rows = []
    saved = []
    for action in actions:
        op = action["op"]
        if op == "put":
            rows.append(action["id"])
        elif op == "delete":
            if action["id"] in rows:
                rows.remove(action["id"])
        elif op == "begin":
            saved = list(rows)
        elif op == "rollback":
            rows = list(saved)
    return sorted(rows)

def next_id(rows):
    return max(rows + [0]) + 1

def investigate(context, acquire):
    return next_id(visible_rows(context["actions"]))

